static void test_orange_orange_black(void)
{
   resistor_value_t actual =
       color_code(std::array{ ORANGE, ORANGE, BLACK }.data());
   TEST_ASSERT_EQUAL_UINT16(33, actual.value);
   TEST_ASSERT_EQUAL(OHMS, actual.unit);
}

