{
   /* All tests enabled by Dev Lab. */
   resistor_value_t actual =
       color_code(std::array{ BLACK, BLACK, BLACK }.data());
   TEST_ASSERT_EQUAL_UINT16(0, actual.value);
   TEST_ASSERT_EQUAL(OHMS, actual.unit);
